        if (state.green || !state.handle) return;
        const devices = world.resource(Devices);
        if (!devices.enabled || !devices.keys.pressed.has("Space")) return;
        world.resource(Materials).update(state.handle, { baseColor: GREEN });
        state.green = true;
    },
};

